const ROUTINES = [
 {name:{en:"Gentle voice warm-up",de:"Sanftes Stimm-Aufwärmen",fr:"Échauffement vocal doux"}, steps:[
  [60,{en:["Posture & release","Stand tall, feet hip-width apart. Roll the shoulders back 5 times, then slowly tilt the head ear-to-shoulder on each side.","Tension in neck and shoulders squeezes the larynx (voice box)."],de:["Haltung & Lockern","Aufrecht stehen, Füße hüftbreit. Schultern 5× nach hinten kreisen, dann den Kopf langsam Ohr zur Schulter neigen, beide Seiten.","Spannung in Nacken und Schultern engt den Kehlkopf ein."],fr:["Posture & détente","Debout, pieds écartés à largeur de hanches. Roulez les épaules vers l'arrière 5 fois, puis inclinez lentement la tête oreille vers épaule, des deux côtés.","Les tensions du cou et des épaules serrent le larynx."]}],
  [45,{en:["Jaw massage","Massage the cheeks in small circles just in front of the ears. Let the jaw hang loose, mouth slightly open.","A relaxed jaw makes room for clear sound."],de:["Kiefermassage","Wangen direkt vor den Ohren in kleinen Kreisen massieren. Kiefer locker hängen lassen, Mund leicht offen.","Ein lockerer Kiefer schafft Raum für klaren Klang."],fr:["Massage de la mâchoire","Massez les joues en petits cercles juste devant les oreilles. Laissez la mâchoire pendre, bouche entrouverte.","Une mâchoire détendue libère un son clair."]}],
  [60,{en:["Belly breathing","Hand on belly. Inhale through the nose 4 s (belly out), exhale on a soft “sss” for 6–8 s.","Builds steady breath support."],de:["Bauchatmung","Hand auf den Bauch. 4 s durch die Nase einatmen (Bauch raus), 6–8 s auf leisem „sss“ ausatmen.","Baut gleichmäßige Atemstütze auf."],fr:["Respiration abdominale","Main sur le ventre. Inspirez par le nez 4 s (ventre qui gonfle), expirez sur un « sss » léger pendant 6–8 s.","Construit un soutien respiratoire régulier."]}],
  [60,{en:["Humming","Lips closed, teeth apart. Hum “mmm” at a comfortable pitch; feel the buzz on lips and nose. 5 breaths.","Humming is a gentle SOVT exercise: vibration with little effort."],de:["Summen","Lippen zu, Zähne auseinander. „mmm“ in bequemer Tonhöhe summen; das Kribbeln an Lippen und Nase spüren. 5 Atemzüge.","Summen ist eine sanfte SOVT-Übung: Schwingung mit wenig Kraft."],fr:["Fredonnement","Lèvres fermées, dents écartées. Fredonnez « mmm » à hauteur confortable ; sentez la vibration sur les lèvres et le nez. 5 respirations.","Le fredonnement est un exercice SOVT doux : vibration avec peu d'effort."]}],
  [60,{en:["Lip trills","Blow through loose lips (“brrr”) and add voice. If the lips stop, support the cheeks lightly with your fingers.","Balances air flow and vocal-fold vibration."],de:["Lippenflattern","Durch lockere Lippen pusten („brrr“) und Stimme dazugeben. Stoppen die Lippen, Wangen leicht mit den Fingern stützen.","Gleicht Luftstrom und Stimmlippenschwingung aus."],fr:["Vibration des lèvres","Soufflez à travers les lèvres relâchées (« brrr ») en ajoutant la voix. Si les lèvres s'arrêtent, soutenez légèrement les joues avec les doigts.","Équilibre le souffle et la vibration des cordes vocales."]}],
  [60,{en:["Sirens","On a lip trill or “ng” (as in “sing”), glide from low to high and back, slowly and smoothly, in a comfortable range.","Stretches and coordinates the vocal folds."],de:["Sirenen","Auf Lippenflattern oder „ng“ (wie in „Ring“) langsam und stufenlos von tief nach hoch und zurück gleiten, im bequemen Bereich.","Dehnt und koordiniert die Stimmlippen."],fr:["Sirènes","Sur la vibration des lèvres ou « ng » (comme dans « parking »), glissez du grave à l'aigu et retour, lentement, sans paliers, dans une zone confortable.","Étire et coordonne les cordes vocales."]}],
  [60,{en:["Straw phonation","Hum or say “ooo” through a drinking straw (or into rounded lips). Make small glides up and down.","Very efficient SOVT exercise; reduces strain."],de:["Strohhalm-Phonation","Durch einen Trinkhalm (oder gerundete Lippen) summen oder „uuu“ sagen. Kleine Gleittöne auf und ab.","Sehr wirksame SOVT-Übung; entlastet die Stimme."],fr:["Phonation à la paille","Fredonnez ou dites « ouuu » dans une paille (ou lèvres arrondies). Faites de petits glissés vers le haut et le bas.","Exercice SOVT très efficace ; réduit l'effort."]}],
  [45,{en:["Yawn–sigh","Start a yawn (throat opens), then let a soft sigh “haaa” fall from high to low.","Opens the throat and relaxes the larynx."],de:["Gähnen–Seufzen","Ein Gähnen beginnen (Hals öffnet sich), dann ein weiches „haaa“ von hoch nach tief fallen lassen.","Öffnet den Rachen und entspannt den Kehlkopf."],fr:["Bâillement–soupir","Commencez un bâillement (la gorge s'ouvre), puis laissez tomber un doux « haaa » de l'aigu au grave.","Ouvre la gorge et détend le larynx."]}]
 ]},
 {name:{en:"Articulation warm-up",de:"Artikulations-Aufwärmen",fr:"Échauffement articulatoire"}, steps:[
  [40,{en:["Lip work","Alternate a wide smile “eee” and a kiss “ooo”, 10 times slowly, then faster.","Mobilises the lip muscles."],de:["Lippen","Abwechselnd breites Lächeln „iii“ und Kussmund „uuu“, 10× langsam, dann schneller.","Mobilisiert die Lippenmuskulatur."],fr:["Lèvres","Alternez un grand sourire « iii » et un bisou « ou », 10 fois lentement, puis plus vite.","Mobilise les muscles des lèvres."]}],
  [45,{en:["Tongue stretches","Tongue out, then up, down, left, right – hold 2 s each. Then circle it around the lips.","Improves tongue range and control."],de:["Zungendehnung","Zunge raus, dann hoch, runter, links, rechts – je 2 s halten. Dann um die Lippen kreisen.","Verbessert Beweglichkeit und Kontrolle der Zunge."],fr:["Étirements de la langue","Langue tirée, puis vers le haut, le bas, la gauche, la droite – 2 s chaque. Puis faites le tour des lèvres.","Améliore l'amplitude et le contrôle de la langue."]}],
  [30,{en:["Tongue clicks","Click the tongue on the palate like a trotting horse, 20 times.","Strengthens the tongue tip."],de:["Zungenschnalzen","Mit der Zunge am Gaumen schnalzen wie Pferdegetrappel, 20×.","Kräftigt die Zungenspitze."],fr:["Claquements de langue","Claquez la langue contre le palais comme un cheval au trot, 20 fois.","Renforce la pointe de la langue."]}],
  [60,{en:["Syllable chain","Say “pa-ta-ka” slowly 5 times, then as fast as possible while still clear, for 10 s.","Fast switching between lips (p), tongue tip (t) and back of the tongue (k)."],de:["Silbenkette","„pa-ta-ka“ 5× langsam, dann 10 s so schnell wie möglich, aber deutlich.","Schneller Wechsel zwischen Lippen (p), Zungenspitze (t) und Hinterzunge (k)."],fr:["Chaîne de syllabes","Dites « pa-ta-ka » 5 fois lentement, puis aussi vite que possible tout en restant net, pendant 10 s.","Alternance rapide lèvres (p), pointe de langue (t) et arrière de langue (k)."]}],
  [60,{en:["Over-articulation","Read any sentence with exaggerated mouth movements, as if for a lip-reader.","Works the muscles through their full range."],de:["Überartikulation","Einen beliebigen Satz mit übertriebenen Mundbewegungen lesen, als ob jemand von den Lippen abliest.","Nutzt den vollen Bewegungsumfang der Muskeln."],fr:["Sur-articulation","Lisez une phrase en exagérant les mouvements de la bouche, comme pour quelqu'un qui lit sur les lèvres.","Fait travailler les muscles sur toute leur amplitude."]}]
 ]},
 {name:{en:"Calm down before speaking",de:"Ruhig werden vor dem Sprechen",fr:"Se calmer avant de parler"}, steps:[
  [40,{en:["Grounding","Feel both feet on the floor. Notice 3 things you can see and 2 you can hear.","Reduces nervousness."],de:["Erden","Beide Füße auf dem Boden spüren. 3 Dinge sehen, 2 Dinge hören.","Verringert Nervosität."],fr:["Ancrage","Sentez vos deux pieds au sol. Repérez 3 choses que vous voyez et 2 que vous entendez.","Réduit la nervosité."]}],
  [90,{en:["Slow breathing","Inhale 4 s through the nose, exhale 6 s through the mouth.","A longer exhale calms the body."],de:["Langsames Atmen","4 s durch die Nase ein, 6 s durch den Mund aus.","Ein längeres Ausatmen beruhigt den Körper."],fr:["Respiration lente","Inspirez 4 s par le nez, expirez 6 s par la bouche.","Une expiration plus longue calme le corps."]}],
  [45,{en:["Hum into speech","Hum “mmm”, then open into “mmm-ah”, “mmm-yes”, “mmm-hello” at speaking pitch.","Finds your comfortable speaking pitch."],de:["Vom Summen ins Sprechen","„mmm“ summen, dann öffnen zu „mmm-ja“, „mmm-hallo“ in Sprechtonlage.","Findet deine bequeme Sprechtonlage."],fr:["Du fredonnement à la parole","Fredonnez « mmm », puis ouvrez sur « mmm-oui », « mmm-bonjour » à hauteur de parole.","Trouve votre hauteur de parole confortable."]}],
  [45,{en:["Say your first sentence","Say the first sentence of your talk or call slowly, with a pause after it. 3 times.","A calm start sets the pace."],de:["Ersten Satz sagen","Den ersten Satz deines Vortrags oder Anrufs langsam sagen, danach Pause. 3×.","Ein ruhiger Start gibt das Tempo vor."],fr:["Dire sa première phrase","Dites lentement la première phrase de votre exposé ou appel, puis faites une pause. 3 fois.","Un début calme donne le rythme."]}]
 ]}
];

